e['headline']:array();						if(count($arrHeadline) > 0){				$title = isset($arrHeadline[0]['title'])?trim($arrHeadline[0]['title']):"";				$alias_old = "parapuan/".url_title($title);								$strQueryHeadline = "SELECT id FROM articles WHERE alias_old = '".$alias_old."'";				$resultRowHeadline = mysqli_query($con, $strQueryHeadline);				$rowCheckArticleHeadline = mysqli_fetch_array($resultRowHeadline, MYSQLI_ASSOC);				$article_id = isset($rowCheckArticleHeadline['id'])?intval($rowCheckArticleHeadline['id']):0;								if(!empty($article_id)){					$strQueryUpdHeadline = "UPDATE articles SET frontpage_category = '1' WHERE id = ".$article_id;					$resultUpdHeadline = mysqli_query($con_master, $strQueryUpdHeadline);										$condition = array("match" => array("id" => $article_id));					$fields = array("id");					$response = $opensearch->findOne("tribunnews-articles", $condition, $fields);										if($response['status']){						$article_id_os = isset($response['data']['_source']['id'])?intval($response['data']['_source']['id']):0;												if($article_id == $article_id_os){							$arrUpdate = array();							$arrUpdate['frontpage_category'] = 1;														$responseUpdate = $opensearch->updateOne("tribunnews-articles", $article_id, $arrUpdate);														if($responseUpdate['status']){								$total++;							}						}					}				}			}		}	}	}	echo "Total Update Headline = ".$total."\n";	unset($opensearch);mysqli_close($con_master);mysqli_close($con);echo "\nExecution time in seconds: ". (microtime(true) - $time_start) . "\n";function url_title($str) {	 $title = strtolower(trim($str));	 $replacements = ['@'=> "at", '#' => "hash", '$' => "dollar", '%' => "percentage", '&' => "and", '.' => "dot", 				'+' => "plus", '-' => "minus", '*' => "multiply", '/' => "devide", '=' => "equal to",				'<' => "less than", '<=' => "less than or equal to", '>' => "greater than", '<=' => "greater than or equal to",		];	 $title = strtr